            height: 28
            font.pixelSize: 13
            verticalAlignment: Text.AlignVCenter
            text: table.currentRow ? qsTr("已选择：%1").arg(table.currentRow.name) : qsTr("尚未选择")
        }
        ETag {
            effect: "plain"
            size: EStyle.Small
            styleType: EStyle.Info
