                : table.sortOrder === "descending" ? qsTr("降序") : qsTr("原始顺序")
        }
        ETextButton {
            size: EStyle.Small
            text: qsTr("清除选择")
            enabled: table.currentRow !== null

            onClicked: table.clearSelection()
        }
        ETextButton {
            size: EStyle.Small
            text: qsTr("清除排序")
            enabled: table.sortOrder.length > 0

            onClicked: table.sort(table.sortProp, "")
        }
    }
    ETable {
        id: table

        stripe: true
